package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type validationIssue struct {
	Row         int
	Description string
}

type validationSummary struct {
	ModelName        string
	ExpectedFeatures int
	TotalRows        int
	ValidRows        int
	InvalidRows      int
	MissingCells     int
	Issues           []validationIssue
}

func cmdValidateInput(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe validate-input <model> --input <file>\n")
		os.Exit(1)
	}

	modelName := args[0]
	flags := parseFlags(args[1:])
	inputFile := flags["input"]
	if inputFile == "" {
		fmt.Fprintf(os.Stderr, "usage: mlpipe validate-input <model> --input <file>\n")
		os.Exit(1)
	}

	entry := resolveModel(modelName)

	weights, err := loadWeights(entry.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading weights: %v\n", err)
		os.Exit(1)
	}

	summary := validateInputFile(entry.Name, inputFile, weights)
	printValidationSummary(summary)
	if summary.InvalidRows > 0 {
		os.Exit(1)
	}
}

func validateInputFile(modelName, inputFile string, weights *WeightsData) *validationSummary {
	records, err := readCSVRaw(inputFile)
	if err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, "file not found")
		} else {
			fmt.Fprintf(os.Stderr, "error reading input: %v\n", err)
		}
		os.Exit(1)
	}

	expected := int(weights.NumFeatures)
	start := 0
	if len(records) > 0 && isHeader(records[0]) {
		start = 1
	}

	summary := &validationSummary{
		ModelName:        modelName,
		ExpectedFeatures: expected,
		TotalRows:        len(records) - start,
	}

	for i := start; i < len(records); i++ {
		record := records[i]
		rowNum := i - start + 1

		var issues []string
		if len(record) != expected {
			issues = append(issues, fmt.Sprintf("expected %d columns, got %d", expected, len(record)))
		} else {
			for j, val := range record {
				if isMissingValue(val) {
					summary.MissingCells++
					issues = append(issues, fmt.Sprintf("missing value in column %d", j+1))
					continue
				}
				if _, err := strconv.ParseFloat(strings.TrimSpace(val), 64); err != nil {
					issues = append(issues, fmt.Sprintf("non-numeric value in column %d: %s", j+1, strings.TrimSpace(val)))
				}
			}
		}

		if len(issues) > 0 {
			summary.InvalidRows++
			summary.Issues = append(summary.Issues, validationIssue{
				Row:         rowNum,
				Description: strings.Join(issues, "; "),
			})
		} else {
			summary.ValidRows++
		}
	}

	return summary
}

func printValidationSummary(summary *validationSummary) {
	fmt.Printf("Validating input for model '%s' (%d features expected)\n", summary.ModelName, summary.ExpectedFeatures)
	fmt.Printf("Total rows:    %d\n", summary.TotalRows)
	fmt.Printf("Valid rows:    %d\n", summary.ValidRows)
	fmt.Printf("Invalid rows:  %d\n", summary.InvalidRows)
	fmt.Printf("Missing values: %d cells\n", summary.MissingCells)

	if len(summary.Issues) > 0 {
		fmt.Println("Issues:")
		limit := len(summary.Issues)
		if limit > 5 {
			limit = 5
		}
		for _, issue := range summary.Issues[:limit] {
			fmt.Printf("  Row %d: %s\n", issue.Row, issue.Description)
		}
	}
}

func cmdSchema(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe schema <model>\n")
		os.Exit(1)
	}

	modelName := args[0]
	entry := resolveModel(modelName)

	meta, err := loadModelMeta(entry.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading metadata: %v\n", err)
		os.Exit(1)
	}

	weights, err := loadWeights(entry.Path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading weights: %v\n", err)
		os.Exit(1)
	}

	featureNames := schemaFeatureNames(meta, int(weights.NumFeatures))

	fmt.Printf("Model: %s\n", entry.Name)
	fmt.Printf("Input features: %d\n", int(weights.NumFeatures))
	for _, name := range featureNames {
		fmt.Printf("  %s: float64\n", name)
	}
	fmt.Printf("Output: %d values\n", int(weights.NumOutputs))
	fmt.Printf("Activation: %s\n", activationIDToName(weights.Activation))
}

func schemaFeatureNames(meta map[string]string, count int) []string {
	names := make([]string, count)
	for i := 0; i < count; i++ {
		names[i] = fmt.Sprintf("f%d", i+1)
	}

	if meta != nil {
		if raw, ok := meta["feature_names"]; ok && strings.TrimSpace(raw) != "" {
			parts := strings.Split(raw, ",")
			for i := 0; i < count; i++ {
				if i < len(parts) {
					name := strings.TrimSpace(parts[i])
					if name != "" {
						names[i] = name
					}
				}
			}
		}
	}

	return names
}
